package estate.svc;

import org.junit.jupiter.api.Test;

import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

class MainTest {
    @Test
    void queuedOfferIsSent() throws Exception {
        FakeContext c = new FakeContext();
        Main m = new Main();
        m.start(c);
        c.tick = 7;
        m.onEvent("offer.queued", Map.of("customerId", "c1", "offerId", "o1"));
        Map<String, String> r = m.handle("sent", Map.of("customerId", "c1"));
        assertEquals("1", r.get("count"));
        assertEquals("7", r.get("ticks"));
        assertEquals("0", r.get("capped"));
    }

    @Test
    void dropsOffersAfterTwoInTheSameDayAndReportsCumulativeDrops() throws Exception {
        FakeContext c = new FakeContext();
        Main m = new Main();
        m.start(c);
        c.tick = 199;
        m.onEvent("offer.queued", Map.of("customerId", "c1", "offerId", "o1"));
        m.onEvent("offer.queued", Map.of("customerId", "c1", "offerId", "o2"));
        m.onEvent("offer.queued", Map.of("customerId", "c1", "offerId", "o3"));
        m.onEvent("offer.queued", Map.of("customerId", "c1", "offerId", "o4"));

        Map<String, String> r = m.handle("sent", Map.of("customerId", "c1"));
        assertEquals("2", r.get("count"));
        assertEquals("199,199", r.get("ticks"));
        assertEquals("2", r.get("capped"));
    }

    @Test
    void doesNotSendQueuedOfferWhenConsentWasRevoked() throws Exception {
        FakeContext c = new FakeContext();
        c.stubs.put("customer.consent.check", req -> Map.of("allowed", "false", "basis", "none"));
        Main m = new Main();
        m.start(c);

        m.onEvent("offer.queued", Map.of("customerId", "c1", "offerId", "o1"));

        Map<String, String> r = m.handle("sent", Map.of("customerId", "c1"));
        assertEquals("0", r.get("count"));
        assertEquals("", r.get("ticks"));
        assertEquals("0", r.get("capped"));
    }

    @Test
    void dailyCapResetsOnTheNextDay() throws Exception {
        FakeContext c = new FakeContext();
        Main m = new Main();
        m.start(c);
        c.tick = 100;
        for (int i = 1; i <= 3; i++) {
            m.onEvent("offer.queued", Map.of("customerId", "c1", "offerId", "o" + i));
        }
        c.tick = 200;
        m.onEvent("offer.queued", Map.of("customerId", "c1", "offerId", "o4"));

        Map<String, String> r = m.handle("sent", Map.of("customerId", "c1"));
        assertEquals("3", r.get("count"));
        assertEquals("100,100,200", r.get("ticks"));
        assertEquals("1", r.get("capped"));
    }

    @Test
    void healthIsUp() throws Exception {
        Main m = new Main();
        m.start(new FakeContext());
        assertEquals("UP", m.handle("health", Map.of()).get("status"));
    }
}
package estate.svc;

import estate.api.Context;
import estate.api.ServiceException;

import java.sql.Connection;
import java.sql.DriverManager;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;

/** Test double for the platform: in-memory H2, stubbed calls, recorded events. */
public class FakeContext implements Context {
    private static final AtomicInteger N = new AtomicInteger();

    public interface Stub { Map<String, String> apply(Map<String, String> req) throws ServiceException; }

    public final Map<String, Stub> stubs = new HashMap<>();
    public final List<String> published = new ArrayList<>();
    public final List<Map<String, String>> events = new ArrayList<>();
    public long tick = 0;
    private final Connection db;

    public FakeContext() {
        try {
            db = DriverManager.getConnection("jdbc:h2:mem:test" + N.incrementAndGet() + ";DB_CLOSE_DELAY=-1");
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    public Connection db() { return db; }

    public Map<String, String> call(String service, String op, Map<String, String> request) throws ServiceException {
        Stub s = stubs.get(service + "." + op);
        if (s == null && "customer".equals(service) && "consent.check".equals(op)) {
            return Map.of("allowed", "true", "basis", "test");
        }
        if (s == null) throw new ServiceException("unavailable", "no stub for " + service + "." + op);
        return s.apply(request);
    }

    public void publish(String topic, Map<String, String> event) { published.add(topic); events.add(event); }

    public long now() { return tick; }
}
